  math:{title:"➕ Mathematik",games:[["mix","🎲","Rechenmix","Gemischte Aufgaben aus dem gewählten Mathebereich."],["quick","⚡","Rechenblitz","Zehn Aufgaben in einer schnellen Runde."],["match","🔗","Rechen-Paare","Verbinde Rechnungen mit dem passenden Ergebnis."]]},
