function mathRand(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function mathChoices(correct,min=0,max=100){let s=new Set([correct]);while(s.size<4){let d=[-10,-5,-2,-1,1,2,5,10][mathRand(0,7)],v=correct+d;if(v>=min&&v<=max)s.add(v)}return [...s].sort(()=>Math.random()-.5)}
function makeMathTask(m){
 let type=m.types[mathRand(0,m.types.length-1)],max=m.max||100,a,b,answer,prompt,choices,suffix="";
 if(type==="compare"){a=mathRand(0,max);do b=mathRand(0,max);while(a===b);answer=a>b?">":"<";prompt=`${a}　?　${b}`;choices=["<",">","="]}
 else if(type==="sequence"){a=mathRand(1,Math.max(3,max-4));answer=a+2;prompt=`${a} · ${a+1} · ? · ${a+3}`;choices=mathChoices(answer,0,max)}
 else if(type==="place"){a=mathRand(10,max);answer=a;prompt=`${Math.floor(a/10)} Zehner + ${a%10} Einer`;choices=mathChoices(answer,0,max)}
 else if(type==="bridgeAdd"){a=mathRand(5,Math.min(89,max-1));b=mathRand(2,9);if(a+b>max||a%10+b<10){a=Math.min(max-2,mathRand(1,Math.max(1,max-10))*10+mathRand(5,9));b=mathRand(Math.max(1,10-a%10),9)}answer=a+b;prompt=`${a} + ${b} = ?`;choices=mathChoices(answer,0,max)}
 else if(type==="bridgeSub"){a=mathRand(11,max);b=mathRand(2,9);if(a-b<0||a%10>=b){a=Math.min(max,mathRand(1,Math.max(1,Math.floor(max/10)))*10+mathRand(0,4));if(a<11)a=11;b=mathRand(Math.max(a%10+1,2),Math.min(9,a))}answer=a-b;prompt=`${a} − ${b} = ?`;choices=mathChoices(answer,0,max)}
 else if(type==="tensAdd"){a=mathRand(1,9)*10;b=mathRand(1,Math.max(1,Math.floor((100-a)/10)))*10;answer=a+b;prompt=`${a} + ${b} = ?`;choices=mathChoices(answer,0,100)}
 else if(type==="tensSub"){a=mathRand(2,10)*10;b=mathRand(1,Math.max(1,a/10-1))*10;answer=a-b;prompt=`${a} − ${b} = ?`;choices=mathChoices(answer,0,100)}
 else if(type==="to100"){a=mathRand(1,9)*10;answer=100-a;prompt=`${a} + ? = 100`;choices=mathChoices(answer,0,100)}
 else if(type==="mul"){let rows=m.rows||[1,2,5,10],r=rows[mathRand(0,rows.length-1)];b=mathRand(0,10);answer=r*b;prompt=`${r} × ${b} = ?`;choices=mathChoices(answer,0,100)}
 else if(type==="div"){let rows=m.rows||[2,5,10],r=rows.filter(x=>x>0)[mathRand(0,rows.filter(x=>x>0).length-1)]||2;b=mathRand(1,10);a=r*b;answer=b;prompt=`${a} ÷ ${r} = ?`;choices=mathChoices(answer,0,100)}
 else if(type==="double"){a=mathRand(1,Math.floor(max/2));answer=a*2;prompt=`Doppelt so viel wie ${a}`;choices=mathChoices(answer,0,max)}
 else if(type==="half"){answer=mathRand(1,Math.floor(max/2));a=answer*2;prompt=`Die Hälfte von ${a}`;choices=mathChoices(answer,0,max)}
 else if(type==="money"){a=mathRand(1,20);b=mathRand(1,20);answer=a+b;prompt=`${a} € + ${b} € = ?`;suffix=" €";choices=mathChoices(answer,0,50)}
 else if(type==="time"){a=mathRand(1,11);b=[0,15,30,45][mathRand(0,3)];let add=[15,30][mathRand(0,1)],mins=a*60+b+add;answer=(Math.floor(mins/60)%24)+":"+(mins%60).toString().padStart(2,"0");prompt=`${a}:${String(b).padStart(2,"0")} Uhr + ${add} Minuten`;choices=[answer,`${a}:${String((b+15)%60).padStart(2,"0")}`,`${(a+1)%24}:${String(b).padStart(2,"0")}`,`${a}:${String((b+30)%60).padStart(2,"0")}`].filter((x,i,z)=>z.indexOf(x)===i);while(choices.length<4)choices.push(`${mathRand(1,12)}:${["00","15","30","45"][mathRand(0,3)]}`);choices=choices.sort(()=>Math.random()-.5)}
 else {a=mathRand(0,max);b=mathRand(0,max-a);if(type==="sub"){a=Math.max(a,b);answer=a-b;prompt=`${a} − ${b} = ?`}else{answer=a+b;prompt=`${a} + ${b} = ?`}choices=mathChoices(answer,0,max)}
 return {type,prompt,answer,choices,suffix}
}
